package content

import (
	"fmt"
	"strings"

	"github.com/rivo/uniseg"
	"github.com/yuin/goldmark"
	"github.com/yuin/goldmark/ast"
	"github.com/yuin/goldmark/extension"
	ext "github.com/yuin/goldmark/extension/ast"
	"github.com/yuin/goldmark/text"
)

// These SGR sequences are generated by MDTUI after untrusted input has been
// filtered. The TUI interprets this small subset itself; it never emits them
// directly to the user's terminal.
const (
	sgrReset     = "\x1b[0m"
	sgrBold      = "\x1b[1m"
	sgrDim       = "\x1b[2m"
	sgrItalic    = "\x1b[3m"
	sgrUnderline = "\x1b[4m"
	sgrStrike    = "\x1b[9m"
	sgrAccent    = "\x1b[38;5;81m"
	sgrAccent2   = "\x1b[38;5;117m"
	sgrMuted     = "\x1b[38;5;245m"
	sgrQuote     = "\x1b[38;5;141m"
	sgrSuccess   = "\x1b[38;5;78m"
	sgrCode      = "\x1b[38;5;222m"
	sgrCodeBG    = "\x1b[48;5;236m"
)

var markdownParser = goldmark.New(goldmark.WithExtensions(extension.GFM))

// Markdown turns Markdown into safe, styled terminal text. Its output contains
// only MDTUI-generated SGR sequences and is consumed by the cell renderer.
func Markdown(source string) string {
	src := []byte(Safe(source))
	root := markdownParser.Parser().Parse(text.NewReader(src))
	r := markdownRenderer{source: src}
	r.blocks(root, 0)
	return strings.TrimRight(r.out.String(), "\n") + sgrReset
}

type markdownRenderer struct {
	source []byte
	out    strings.Builder
}

func (r *markdownRenderer) blocks(parent ast.Node, depth int) {
	for node := parent.FirstChild(); node != nil; node = node.NextSibling() {
		switch n := node.(type) {
		case *ast.Heading:
			prefix := "▍ "
			style := sgrBold + sgrAccent
			if n.Level > 1 {
				prefix = strings.Repeat("›", min(n.Level-1, 3)) + " "
				style = sgrBold + sgrAccent2
			}
			r.out.WriteString(style + prefix + r.inlineChildren(n) + sgrReset + "\n")
			if n.Level == 1 {
				plain := stripSGR(r.inlineChildren(n))
				r.out.WriteString(sgrDim + sgrAccent + strings.Repeat("─", max(4, uniseg.StringWidth(plain)+2)) + sgrReset + "\n")
			}
		case *ast.Paragraph, *ast.TextBlock:
			r.out.WriteString(strings.Repeat("  ", depth) + r.inlineChildren(n) + sgrReset + "\n")
		case *ast.List:
			r.list(n, depth)
		case *ast.Blockquote:
			var nested markdownRenderer
			nested.source = r.source
			nested.blocks(n, 0)
			for _, line := range strings.Split(strings.TrimRight(nested.out.String(), "\n"), "\n") {
				r.out.WriteString(strings.Repeat("  ", depth) + sgrQuote + "│ " + sgrReset + line + "\n")
			}
		case *ast.FencedCodeBlock:
			r.code(n.Lines(), string(n.Language(r.source)), depth)
		case *ast.CodeBlock:
			r.code(n.Lines(), "", depth)
		case *ast.ThematicBreak:
			r.out.WriteString(strings.Repeat("  ", depth) + sgrMuted + "╶────────────────────────╴" + sgrReset + "\n")
		case *ext.Table:
			r.table(n, depth)
		case *ast.HTMLBlock:
			r.out.WriteString(strings.Repeat("  ", depth) + sgrDim + "‹HTML› " + sgrReset)
			for i := 0; i < n.Lines().Len(); i++ {
				segment := n.Lines().At(i)
				r.out.Write(segment.Value(r.source))
			}
			r.out.WriteString(sgrReset + "\n")
		default:
			if node.HasChildren() {
				r.blocks(node, depth)
			}
		}
	}
}

func (r *markdownRenderer) list(list *ast.List, depth int) {
	index := list.Start
	for child := list.FirstChild(); child != nil; child = child.NextSibling() {
		item, ok := child.(*ast.ListItem)
		if !ok {
			continue
		}
		marker := "•"
		if list.IsOrdered() {
			marker = fmt.Sprintf("%d.", index)
			index++
		}
		indent := strings.Repeat("  ", depth)
		first := true
		for part := item.FirstChild(); part != nil; part = part.NextSibling() {
			switch v := part.(type) {
			case *ast.Paragraph, *ast.TextBlock:
				if first {
					r.out.WriteString(indent + sgrAccent + marker + sgrReset + " " + r.inlineChildren(v) + sgrReset + "\n")
					first = false
				} else {
					r.out.WriteString(indent + "  " + r.inlineChildren(v) + sgrReset + "\n")
				}
			case *ast.List:
				r.list(v, depth+1)
			default:
				if v.HasChildren() {
					r.blocks(v, depth+1)
				}
			}
		}
	}
}

func (r *markdownRenderer) code(lines *text.Segments, language string, depth int) {
	indent := strings.Repeat("  ", depth)
	label := "code"
	if language != "" {
		label += " · " + language
	}
	r.out.WriteString(indent + sgrMuted + "╭─ " + label + sgrReset + "\n")
	for i := 0; i < lines.Len(); i++ {
		segment := lines.At(i)
		line := strings.TrimSuffix(string(segment.Value(r.source)), "\n")
		r.out.WriteString(indent + sgrMuted + "│ " + sgrReset + sgrCodeBG + sgrCode + " " + line + " " + sgrReset + "\n")
	}
	r.out.WriteString(indent + sgrMuted + "╰─" + sgrReset + "\n")
}

func (r *markdownRenderer) table(table *ext.Table, depth int) {
	var rows [][]tableValue
	for row := table.FirstChild(); row != nil; row = row.NextSibling() {
		var values []tableValue
		for cell := row.FirstChild(); cell != nil; cell = cell.NextSibling() {
			c, ok := cell.(*ext.TableCell)
			if !ok {
				continue
			}
			styled := r.inlineChildren(c)
			values = append(values, tableValue{styled: styled, plain: stripSGR(styled), alignment: c.Alignment})
		}
		rows = append(rows, values)
	}
	if len(rows) == 0 {
		return
	}
	columns := 0
	for _, row := range rows {
		columns = max(columns, len(row))
	}
	widths := make([]int, columns)
	for _, row := range rows {
		for column, cell := range row {
			widths[column] = max(widths[column], uniseg.StringWidth(cell.plain))
		}
	}
	indent := strings.Repeat("  ", depth)
	border := func(left, middle, right string) {
		r.out.WriteString(indent + sgrMuted + left)
		for i, width := range widths {
			if i > 0 {
				r.out.WriteString(middle)
			}
			r.out.WriteString(strings.Repeat("─", width+2))
		}
		r.out.WriteString(right + sgrReset + "\n")
	}
	border("╭", "┬", "╮")
	for rowIndex, row := range rows {
		r.out.WriteString(indent + sgrMuted + "│" + sgrReset)
		for column, width := range widths {
			cell := tableValue{}
			if column < len(row) {
				cell = row[column]
			}
			value := alignTable(cell, width)
			if rowIndex == 0 {
				value = sgrBold + sgrAccent2 + value + sgrReset
			}
			r.out.WriteString(" " + value + " " + sgrMuted + "│" + sgrReset)
		}
		r.out.WriteByte('\n')
		if rowIndex == 0 && len(rows) > 1 {
			border("├", "┼", "┤")
		}
	}
	border("╰", "┴", "╯")
}

type tableValue struct {
	styled    string
	plain     string
	alignment ext.Alignment
}

func alignTable(cell tableValue, width int) string {
	missing := max(0, width-uniseg.StringWidth(cell.plain))
	switch cell.alignment {
	case ext.AlignRight:
		return strings.Repeat(" ", missing) + cell.styled
	case ext.AlignCenter:
		left := missing / 2
		return strings.Repeat(" ", left) + cell.styled + strings.Repeat(" ", missing-left)
	default:
		return cell.styled + strings.Repeat(" ", missing)
	}
}

func (r *markdownRenderer) inlineChildren(parent ast.Node) string {
	var out strings.Builder
	for child := parent.FirstChild(); child != nil; child = child.NextSibling() {
		r.inline(&out, child)
	}
	return out.String()
}

func (r *markdownRenderer) inline(out *strings.Builder, node ast.Node) {
	switch n := node.(type) {
	case *ast.Text:
		out.Write(n.Segment.Value(r.source))
		if n.SoftLineBreak() || n.HardLineBreak() {
			out.WriteByte('\n')
		}
	case *ast.String:
		out.Write(n.Value)
	case *ast.CodeSpan:
		out.WriteString(sgrCodeBG + sgrCode + " ")
		for child := n.FirstChild(); child != nil; child = child.NextSibling() {
			r.inline(out, child)
		}
		out.WriteString(" " + sgrReset)
	case *ast.Emphasis:
		if n.Level == 2 {
			out.WriteString(sgrBold)
		} else {
			out.WriteString(sgrItalic)
		}
		out.WriteString(r.inlineChildren(n) + sgrReset)
	case *ext.Strikethrough:
		out.WriteString(sgrStrike + r.inlineChildren(n) + sgrReset)
	case *ast.Link:
		out.WriteString(sgrAccent + sgrUnderline + r.inlineChildren(n) + sgrReset)
		out.WriteString(sgrDim + " (" + string(n.Destination) + ")" + sgrReset)
	case *ast.AutoLink:
		out.WriteString(sgrAccent + sgrUnderline + string(n.Label(r.source)) + sgrReset)
	case *ast.Image:
		out.WriteString(sgrQuote + "▧ " + r.inlineChildren(n) + sgrReset)
		if len(n.Destination) > 0 {
			out.WriteString(sgrDim + " (" + string(n.Destination) + ")" + sgrReset)
		}
	case *ext.TaskCheckBox:
		if n.IsChecked {
			out.WriteString(sgrSuccess + "☑" + sgrReset + " ")
		} else {
			out.WriteString(sgrMuted + "☐" + sgrReset + " ")
		}
	case *ast.RawHTML:
		out.WriteString(sgrDim)
		for i := 0; i < n.Segments.Len(); i++ {
			segment := n.Segments.At(i)
			out.Write(segment.Value(r.source))
		}
		out.WriteString(sgrReset)
	default:
		for child := node.FirstChild(); child != nil; child = child.NextSibling() {
			r.inline(out, child)
		}
	}
}

func stripSGR(value string) string {
	var out strings.Builder
	for i := 0; i < len(value); {
		if value[i] == 0x1b && i+1 < len(value) && value[i+1] == '[' {
			i += 2
			for i < len(value) && (value[i] < '@' || value[i] > '~') {
				i++
			}
			if i < len(value) {
				i++
			}
			continue
		}
		out.WriteByte(value[i])
		i++
	}
	return out.String()
}
